function createSignatureArt(entry){if(entry.drawing.pixels)return pixelArtwork(entry);const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox','0 0 540 180');svg.setAttribute('class','signature-art');svg.setAttribute('role','img');svg.setAttribute('aria-label',`signature of ${entry.name}`);if(entry.drawing.typed){const text=document.createElementNS(ns,'text');text.setAttribute('x','270');text.setAttribute('y','90');text.setAttribute('fill',entry.ink);text.setAttribute('class','typed-art');text.textContent=entry.drawing.typed;svg.append(text)}else{for(const stroke of entry.drawing.strokes){const path=document.createElementNS(ns,'path');path.setAttribute('d',signaturePath(stroke));path.setAttribute('fill','none');path.setAttribute('stroke',entry.ink);svg.append(path)}}return svg}
